  // lhs = a, rhs = b
  // lhs_contracting_dimensions = [0] (k dimension in a)
  // rhs_contracting_dimensions = [0] (k dimension in b)
  // lhs_batching_dimensions = []
  // rhs_batching_dimensions = []
  // lhs_result_dimensions = [1] (i dimension in a)
  // rhs_result_dimensions = [1] (j dimension in b)
