  // Broadcast x from [2,5] to [2,3,5] by adding a new dimension at dim=1
  %x_broadcast = stablehlo.broadcast_in_dim %x 
    {broadcast_dimensions = dense<array<i64: 0, 2>> : tensor<2xi64>} : (tensor<2x5xf32>) -> tensor<2x1x5xf32>
  %x_broadcast_reshaped = stablehlo.broadcast_in_dim %x_broadcast
    {broadcast_dimensions = dense<array<i64: 0, 2, 3>> : tensor<3xi64>} : (tensor<2x1x5xf32>) -> tensor<2x3x5xf32>

  // Broadcast y from [3,5] to [2,3,5] by adding a new dimension at dim=0
  %y_broadcast = stablehlo.broadcast_in_dim %y
    {broadcast_dimensions = dense<array<i64: 1, 2>> : tensor<2xi64>} : (tensor<3x5xf32>) -> tensor<1x3x5xf32>
  %y_broadcast_reshaped = stablehlo.broadcast_in_dim %y_broadcast
    {broadcast_dimensions = dense<array<i64: 0, 1, 2>> : tensor<3xi64>} : (tensor<1x3x5xf32>) -> tensor<2x3x5xf32>

  // Compute difference (x[i,d] - y[j,d]) broadcasted to [2,3,5]
