    ( {
      ^bb0(%a: tensor<f32>, %b: tensor<f32>):
        %sum = stablehlo.add %a, %b : tensor<f32>
        stablehlo.return %sum : tensor<f32>
    }) {dimensions = dense<array<i64: 2>> : tensor<1xi64>} : (tensor<2x3x5xf32>, tensor<f32>) -> tensor<2x3xf32>

  return %out : tensor<2x3xf32>
