func.func @main(%x: tensor<4x3xf32>) -> tensor<4x3xf32> {
  // Compute squares of elements: x^2
  %squared = stablehlo.multiply %x, %x : tensor<4x3xf32>

  // Reduce sum of squares along dimension 1 (columns) to get sum_k x[i,k]^2 for each row i
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_squares = stablehlo.reduce %squared, %init {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<1> : tensor<1xi64>} : (tensor<4x3xf32>, tensor<f32>) -> tensor<4xf32>

  // Compute sqrt of sum_squares for each row
  %sqrt_sum = stablehlo.sqrt %sum_squares : tensor<4xf32>

  // Broadcast sqrt_sum to shape 4x3 to match x shape for division
  %broadcast_dims = stablehlo.constant dense<[0, -1]> : tensor<2xi64>  // Actually we need [0] for broadcast_in_dim
  %broadcast_dims = stablehlo.constant dense<[0]> : tensor<1xi64>
  %sqrt_sum_broadcast = stablehlo.broadcast_in_dim %sqrt_sum 
    {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : tensor<4xf32> -> tensor<4x3xf32>

  // Divide x by broadcasted sqrt_sum to normalize each row
  %out = stablehlo.divide %x, %sqrt_sum_broadcast : tensor<4x3xf32>

  stablehlo.return %out : tensor<4x3xf32>
}
