func.func @main(%x: tensor<5x8xf32>, %i: tensor<i32>) -> tensor<2x8xf32> {
  // Clamp i to the range [0, 3]
  %c0 = stablehlo.constant 0 : tensor<i32>
  %c3 = stablehlo.constant 3 : tensor<i32>
  %max_i_0 = stablehlo.maximum %i, %c0 : tensor<i32>
  %clamped_i = stablehlo.minimum %max_i_0, %c3 : tensor<i32>

  // Prepare start indices for dynamic_slice: [clamped_i, 0]
  %c0_8 = stablehlo.constant 0 : tensor<i32>
  %start_indices = stablehlo.concatenate %clamped_i, %c0_8 {dimension = 0} : tensor<i32>, tensor<i32> -> tensor<2xi32>

  // Slice sizes: [2, 8]
  %slice_sizes = stablehlo.constant dense<2, 8> : tensor<2xi64>

  // dynamic_slice expects start indices as a tensor of rank equal to operand rank (2),
  // but each index is a scalar tensor. We need to pass start indices as a tensor<2xi32>.
  // The stablehlo.dynamic_slice op expects start indices as a tensor<rank x i32> or a list of scalars?
  // According to docs, start indices are tensors of shape [rank], so tensor<2xi32> is correct.

  %result = stablehlo.dynamic_slice %x, %start_indices {slice_sizes = dense<2, 8> : tensor<2xi64>} : (tensor<5x8xf32>, tensor<2xi32>) -> tensor<2x8xf32>
  return %result : tensor<2x8xf32>
}
