func.func @main(%x: tensor<4x5xf32>) -> tensor<4x5xf32> {
  // Compute max over dim 1 for numerical stability: max[i] = max_j x[i,j]
  %c_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf for f32
  %init_max = stablehlo.broadcast_in_dim %c_neg_inf : tensor<f32> to tensor<4x1xf32> {broadcast_dimensions = [0, 1]}
  %max = stablehlo.reduce %x, %init_max {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<1> : tensor<1xi64>} : (tensor<4x5xf32>, tensor<4x1xf32>) -> tensor<4x1xf32>

  // Broadcast max to shape of x for subtraction
  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<4x1xf32> to tensor<4x5xf32> {broadcast_dimensions = [0, 1]}

  // Subtract max for numerical stability
  %x_stable = stablehlo.subtract %x, %max_broadcast : tensor<4x5xf32>

  // Compute exp(x - max)
  %exp = stablehlo.exponential %x_stable : tensor<4x5xf32>

  // Sum exp over dim 1
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_sum = stablehlo.broadcast_in_dim %init_zero : tensor<f32> to tensor<4x1xf32> {broadcast_dimensions = [0, 1]}
  %sum_exp = stablehlo.reduce %exp, %init_sum {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>): tensor<f32> {
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
  } {dimensions = dense<1> : tensor<1xi64>} : (tensor<4x5xf32>, tensor<4x1xf32>) -> tensor<4x1xf32>

  // Broadcast sum_exp to shape of x for division
